#!/usr/bin/env python3
"""Derives lib/w2r1/generated/vor-fast.ts from the FROZEN lib/w2r1/vor.ts by asserted substitutions (frozen file untouched): scenario/top-candidate lookups go through the per-request memo."""
s = open("lib/w2r1/vor.ts").read()
def sub(x, o, n):
    assert x.count(o) == 1, (o, x.count(o)); return x.replace(o, n)
s = sub(s, 'import { chainBetween, scenarioLineup, topCandidates, weekValue, type ChainStep } from "./roster";', 'import { chainBetween, weekValue, type ChainStep } from "../roster";\nimport { cachedScenarioLineup as scenarioLineup, cachedTopCandidates as topCandidates } from "../scenario-cache";')
s = sub(s, 'import { W2R1_LABEL, W2R1_MODEL_VERSION, W2R1_MODE } from "./version";', 'import { W2R1_LABEL, W2R1_MODEL_VERSION, W2R1_MODE } from "../version";')
s = sub(s, 'import type { LeagueRules, MarketCandidate, MarketPool, Pos, RosterAsset } from "./evidence";', 'import type { LeagueRules, MarketCandidate, MarketPool, Pos, RosterAsset } from "../evidence";')
s = "// GENERATED by scripts/w2r1/perf/make_vor_fast.py from the FROZEN lib/w2r1/vor.ts — do not edit. Behavior is identical (test-enforced); only scenario evaluation is memoized per request.\n" + s
import sys
out = sys.argv[1] if len(sys.argv) > 1 else "lib/w2r1/generated/vor-fast.ts"
open(out, "w").write(s); print("ok")
